namespace sv_d4765e8256f046f8a8d5b18f96e4c34f.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_d4765e8256f046f8a8d5b18f96e4c34f.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application steps">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => OnStepClick(stepIndex)">
                <span class="step-marker">
                    @if (status == "completed")
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnNavigateToStep { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepStatus(int index)
    {
        if (index == CurrentStep) return "active";
        if (index < CurrentStep) return "completed";
        return "dimmed";
    }

    private async Task OnStepClick(int index)
    {
        if (index < CurrentStep)
        {
            await OnNavigateToStep.InvokeAsync(index);
        }
    }
}

@namespace sv_d4765e8256f046f8a8d5b18f96e4c34f.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company"
               @onchange="e => UpdateEntry(Entry with { Company = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title"
               @onchange="e => UpdateEntry(Entry with { Title = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateEntry(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")"
                   disabled="@IsCurrent"
                   @onchange="e => UpdateEntry(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => ToggleCurrent((bool?)e.Value ?? false)" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description"
                  @onchange="e => UpdateEntry(Entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private async Task UpdateEntry(WorkEntryModel updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }

    private async Task ToggleCurrent(bool isCurrent)
    {
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        await OnEntryChanged.InvokeAsync(updated);
    }
}

@namespace sv_d4765e8256f046f8a8d5b18f96e4c34f.Components.Pages.Apply

<div class="reference-card">
    <div class="reference-header">
        <h4>Reference @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" value="@Reference.Name"
                   @onchange="e => Update(Reference with { Name = (string?)e.Value ?? string.Empty })" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" value="@Reference.Relationship"
                   @onchange="e => Update(Reference with { Relationship = (string?)e.Value ?? string.Empty })" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Reference.Email"
                   @onchange="e => Update(Reference with { Email = (string?)e.Value ?? string.Empty })" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" value="@Reference.Phone"
                   @onchange="e => Update(Reference with { Phone = (string?)e.Value ?? string.Empty })" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Reference { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<ReferenceModel> OnReferenceChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private async Task Update(ReferenceModel updated)
    {
        await OnReferenceChanged.InvokeAsync(updated);
    }
}

@namespace sv_d4765e8256f046f8a8d5b18f96e4c34f.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@Model.FullName"
               @onchange="e => UpdateModel(Model with { FullName = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Model.Email"
               @onchange="e => UpdateModel(Model with { Email = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Model.Phone"
               @onchange="e => UpdateModel(Model with { Phone = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Model.Address"
                  @onchange="e => UpdateModel(Model with { Address = (string?)e.Value ?? string.Empty })"></textarea>
    </div>

    <div class="step-buttons">
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback<PersonalInfoModel> OnModelChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ErrorMessage;
    private bool IsValidating;

    private async Task UpdateModel(PersonalInfoModel updated)
    {
        await OnModelChanged.InvokeAsync(updated);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Model.Email);
            IsValidating = false;

            if (!isValid)
            {
                ErrorMessage = "The email address is not valid.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_d4765e8256f046f8a8d5b18f96e4c34f.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       CanRemove="@(Entries.Count > 1)"
                       OnEntryChanged="e => HandleEntryChanged(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback<List<WorkEntryModel>> OnEntriesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private async Task HandleEntryChanged(int index, WorkEntryModel updated)
    {
        var list = new List<WorkEntryModel>(Entries);
        list[index] = updated;
        await OnEntriesChanged.InvokeAsync(list);
    }

    private async Task AddEntry()
    {
        var list = new List<WorkEntryModel>(Entries)
        {
            new()
        };
        await OnEntriesChanged.InvokeAsync(list);
    }

    private async Task RemoveEntry(int index)
    {
        var list = new List<WorkEntryModel>(Entries);
        list.RemoveAt(index);
        await OnEntriesChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) ||
                string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default)
            {
                ErrorMessage = "Company, title, and start date are required for each position.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_d4765e8256f046f8a8d5b18f96e4c34f.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Reference="@References[index]"
                       Index="index"
                       CanRemove="@(References.Count > 2)"
                       OnReferenceChanged="e => HandleReferenceChanged(index, e)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public EventCallback<List<ReferenceModel>> OnReferencesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private async Task HandleReferenceChanged(int index, ReferenceModel updated)
    {
        var list = new List<ReferenceModel>(References);
        list[index] = updated;
        await OnReferencesChanged.InvokeAsync(list);
    }

    private async Task AddReference()
    {
        if (References.Count < 3)
        {
            var list = new List<ReferenceModel>(References) { new() };
            await OnReferencesChanged.InvokeAsync(list);
        }
    }

    private async Task RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            var list = new List<ReferenceModel>(References);
            list.RemoveAt(index);
            await OnReferencesChanged.InvokeAsync(list);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) ||
                string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Name, relationship, and email are required for each reference.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_d4765e8256f046f8a8d5b18f96e4c34f.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Write your cover letter below:</label>
        <textarea rows="12" maxlength="2000" value="@CoverLetter"
                  @oninput="HandleInput"></textarea>
        <div class="char-count">@CoverLetter.Length / 2000 characters</div>
    </div>

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> OnCoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = (string?)e.Value ?? string.Empty;
        if (value.Length <= 2000)
        {
            await OnCoverLetterChanged.InvokeAsync(value);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ErrorMessage = "Please write a cover letter before proceeding.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_d4765e8256f046f8a8d5b18f96e4c34f.Components.Pages.Apply

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    @if (IsSubmitted)
    {
        <div class="confirmation">
            <h3>&#10003; Application Submitted Successfully!</h3>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-item">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="review-dates">
                        @entry.StartDate.ToString("MMM yyyy") &ndash;
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-item">
                    <strong>@r.Name</strong> (@r.Relationship)
                    <br />@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"| {r.Phone}" : "")
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        <div class="step-buttons">
            <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
            <button type="button" class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
